export default async function AdminPage() {
  const { isAdmin, session } = await verifyAdmin()

  // Trigger Next.js's auth boundary, which renders the nearest `forbidden.tsx`
  // and responds with a 403 Forbidden status code.
  if (!isAdmin) {
    forbidden()
  }

  return (
    <main>
      <h1>Admin Dashboard</h1>
      <p>Welcome, {session?.name}. You have admin access.</p>
    </main>
  )
}

